51	        Validate.notNull(safelist);
52	        this.safelist = safelist;
53	    }
54	
55	    /**
56	     Creates a new, clean document, from the original dirty document, containing only elements allowed by the safelist.
57	     The original document is not modified. Only elements from the dirty document's <code>body</code> are used. The
58	     OutputSettings of the original document are cloned into the clean document.
59	     @param dirtyDocument Untrusted base document to clean.
60	     @return cleaned document.
61	     */
62	    public Document clean(Document dirtyDocument) {
63	        Validate.notNull(dirtyDocument);
64	
65	        Document clean = Document.createShell(dirtyDocument.baseUri());
66	        copySafeNodes(dirtyDocument.body(), clean.body());
67	        clean.outputSettings(dirtyDocument.outputSettings().clone());
68	
69	        return clean;
70	    }
71	
72	    /**
73	     Determines if the input document's <b>body</b> is valid, against the safelist. It is considered valid if all the
74	     tags and attributes in the input HTML are allowed by the safelist, and that there is no content in the
75	     <code>head</code>.
76	     <p>
77	     This method is intended to be used in a user interface as a validator for user input. Note that regardless of the
78	     output of this method, the input document <b>must always</b> be normalized using a method such as
79	     {@link #clean(Document)}, and the result of that method used to store or serialize the document before later reuse
80	     such as presentation to end users. This ensures that enforced attributes are set correctly, and that any
81	     differences between how a given browser and how jsoup parses the input HTML are normalized.
82	     </p>
83	     <p>Example:
84	     <pre>{@code
85	     Document inputDoc = Jsoup.parse(inputHtml);
86	     Cleaner cleaner = new Cleaner(Safelist.relaxed());
87	     boolean isValid = cleaner.isValid(inputDoc);
88	     Document normalizedDoc = cleaner.clean(inputDoc);
89	     }</pre>
90	     </p>
91	     @param dirtyDocument document to test
92	     @return true if no tags or attributes need to be removed; false if they do
93	     */
94	    public boolean isValid(Document dirtyDocument) {
95	        Validate.notNull(dirtyDocument);
96	
97	        Document clean = Document.createShell(dirtyDocument.baseUri());
98	        int numDiscarded = copySafeNodes(dirtyDocument.body(), clean.body());
99	        return numDiscarded == 0
100	            && dirtyDocument.head().childNodes().isEmpty(); // because we only look at the body, but we start from a shell, make sure there's nothing in the head
101	    }
102	
103	    /**
104	     Determines if the input document's <b>body HTML</b> is valid, against the safelist. It is considered valid if all
105	     the tags and attributes in the input HTML are allowed by the safelist.
106	     <p>
107	     This method is intended to be used in a user interface as a validator for user input. Note that regardless of the
108	     output of this method, the input document <b>must always</b> be normalized using a method such as
109	     {@link #clean(Document)}, and the result of that method used to store or serialize the document before later reuse
110	     such as presentation to end users. This ensures that enforced attributes are set correctly, and that any
111	     differences between how a given browser and how jsoup parses the input HTML are normalized.
112	     </p>
113	     <p>Example:
114	     <pre>{@code
115	     Document inputDoc = Jsoup.parse(inputHtml);
116	     Cleaner cleaner = new Cleaner(Safelist.relaxed());
117	     boolean isValid = cleaner.isValidBodyHtml(inputHtml);
118	     Document normalizedDoc = cleaner.clean(inputDoc);
119	     }</pre>
120	     </p>
121	     @param bodyHtml HTML fragment to test
122	     @return true if no tags or attributes need to be removed; false if they do
123	     */
124	    public boolean isValidBodyHtml(String bodyHtml) {
125	        String baseUri = (safelist.preserveRelativeLinks()) ? DummyUri : ""; // fake base URI to allow relative URLs to remain valid
126	        Document clean = Document.createShell(baseUri);
127	        Document dirty = Document.createShell(baseUri);
128	        ParseErrorList errorList = ParseErrorList.tracking(1);
129	        List<Node> nodes = Parser.parseFragment(bodyHtml, dirty.body(), baseUri, errorList);
130	        dirty.body().insertChildren(0, nodes);
131	        int numDiscarded = copySafeNodes(dirty.body(), clean.body());
132	        return numDiscarded == 0 && errorList.isEmpty();
133	    }
134	
135	    /**
136	     Iterates the input and copies trusted nodes (tags, attributes, text) into the destination.
137	     */
138	    private final class CleaningVisitor implements NodeVisitor {
139	        private int numDiscarded = 0;
140	        private final Element root;
141	        private Element destination; // current element to append nodes to
142	
143	        private CleaningVisitor(Element root, Element destination) {
144	            this.root = root;
145	            this.destination = destination;
146	        }
147	
148	        @Override public void head(Node source, int depth) {
149	            if (source instanceof Element) {
150	                Element sourceEl = (Element) source;
151	
152	                if (safelist.isSafeTag(sourceEl.normalName())) { // safe, clone and copy safe attrs
153	                    ElementMeta meta = createSafeElement(sourceEl);
154	                    Element destChild = meta.el;
155	                    destination.appendChild(destChild);
156	
157	                    numDiscarded += meta.numAttribsDiscarded;
158	                    destination = destChild;
159	                } else if (source != root) { // not a safe tag, so don't add. don't count root against discarded.
160	                    numDiscarded++;
161	                }
162	            } else if (source instanceof TextNode) {
163	                TextNode sourceText = (TextNode) source;
164	                TextNode destText = new TextNode(sourceText.getWholeText());
165	                destination.appendChild(destText);
166	            } else if (source instanceof DataNode && safelist.isSafeTag(source.parent().normalName())) {
167	                DataNode sourceData = (DataNode) source;
168	                DataNode destData = new DataNode(sourceData.getWholeData());
169	                destination.appendChild(destData);
170	            } else { // else, we don't care about comments, xml proc instructions, etc
171	                numDiscarded++;
172	            }
173	        }
174	
175	        @Override public void tail(Node source, int depth) {
176	            if (source instanceof Element && safelist.isSafeTag(source.normalName())) {
177	                destination = destination.parent(); // would have descended, so pop destination stack
178	            }
179	        }
180	    }
181	
182	    private int copySafeNodes(Element source, Element dest) {
183	        CleaningVisitor cleaningVisitor = new CleaningVisitor(source, dest);
184	        cleaningVisitor.traverse(source);
185	        return cleaningVisitor.numDiscarded;
186	    }
187	
188	    private ElementMeta createSafeElement(Element sourceEl) {
189	        Element dest = sourceEl.shallowClone(); // reuses tag, clones attributes and preserves any user data
190	        String sourceTag = sourceEl.tagName();
191	        Attributes destAttrs = dest.attributes();
192	        dest.clearAttributes(); // clear all non-internal attributes, ready for safe copy
193	
194	        int numDiscarded = 0;
195	        Attributes sourceAttrs = sourceEl.attributes();
196	        for (Attribute sourceAttr : sourceAttrs) {
197	            // srcset is structurally allowed like any attribute, but its value holds several candidate URLs which are
198	            // validated individually below, so it must not go through the ordinary whole-value protocol test.
199	            boolean attrAllowed = SrcsetCleaner.isSrcset(sourceAttr)
200	                ? safelist.isAllowedAttribute(sourceTag, sourceEl, sourceAttr)
201	                : safelist.isSafeAttribute(sourceTag, sourceEl, sourceAttr);
202	            if (attrAllowed) { // will keep this attr
203	                String key = sourceAttr.getKey();
204	                String value = sourceAttr.getValue();
205	
206	                if (SrcsetCleaner.isSrcset(sourceAttr)) {
207	                    // validate and rewrite each candidate instead of treating the whole value as one opaque URL
208	                    SrcsetCleaner.Result srcset = SrcsetCleaner.clean(sourceEl, value, safelist);
209	                    if (srcset.removed) { // no acceptable candidate: remove the attribute, never leave it empty
210	                        numDiscarded += 1 + srcset.droppedCandidates;
211	                        continue;
212	                    }
213	                    numDiscarded += srcset.droppedCandidates;
214	                    value = srcset.value;
215	                } else if (safelist.shouldAbsUrl(sourceTag, key)) { // configured to make absolute urls for this key (href)
216	                    value = sourceEl.absUrl(key);
217	                    if (value.isEmpty()) // could not be made abs; leave as-is to allow custom unknown protocols
218	                        value = sourceAttr.getValue();
219	                }
220	                Range.AttributeRange range = sourceAttrs.sourceRange(key);
221	                destAttrs.put(key, value);
222	                NodeInternals.attributeRange(destAttrs, key, range);
223	            } else
224	                numDiscarded++;
225	        }
226	
227	        Attributes enforcedAttrs = safelist.getEnforcedAttributes(sourceTag);
228	        // special case for <a href rel=nofollow>, only apply to external links:
229	        if (sourceEl.nameIs("a") && enforcedAttrs.get("rel").equals("nofollow")) {
230	            String href = sourceEl.absUrl("href");
231	            if (!href.isEmpty()) {
232	                try {
233	                    URL baseUrl = new URL(sourceEl.baseUri());
234	                    URL linkUrl = new URL(href);
235	                    String baseHost = baseUrl.getHost();
236	                    if (!baseHost.isEmpty() && baseHost.equalsIgnoreCase(linkUrl.getHost())) // same site, so don't set the nofollow
237	                        enforcedAttrs.remove("rel");
238	                } catch (MalformedURLException ignored) {}
239	            }
240	        }
241	
242	        // apply enforced attributes case-insensitively, so a preserved-case source attr is canonicalized to the enforced key
243	        for (Attribute enforcedAttr : enforcedAttrs) {
244	            destAttrs.removeIgnoreCase(enforcedAttr.getKey());
245	            destAttrs.put(enforcedAttr.getKey(), enforcedAttr.getValue());
246	        }
247	        dest.attributes().addAll(destAttrs); // re-attach, if removed in clear
248	        return new ElementMeta(dest, numDiscarded);
249	    }
250	
251	    private static class ElementMeta {
252	        Element el;
253	        int numAttribsDiscarded;
254	
255	        ElementMeta(Element el, int numAttribsDiscarded) {
256	            this.el = el;
257	            this.numAttribsDiscarded = numAttribsDiscarded;
258	        }
259	    }
260	
261	}
