503	        // quoted address drops its delimiting quotes; the whitespace-containing quoted address is dropped alone;
504	        // empty/leading/trailing commas do not swallow following candidates
505	        assertEquals("<source srcset=\"http://example.com/a,b.jpg 1x, http://example.com/b.jpg 2x\">", clean);
506	    }
507	
508	    @Test void unterminatedQuoteOnSourceResyncsAtComma() {
509	        String html = "<picture><source media=\"(x)\" srcset='\"http://example.com/a.jpg 1x, http://example.com/b.jpg 2x'>"
510	            + "<img src=\"/f.jpg\"></picture>";
511	        String clean = Jsoup.clean(html, "http://example.com/", pictureSafelist());
512	        assertEquals("<picture><source media=\"(x)\" srcset=\"http://example.com/b.jpg 2x\">"
513	            + "<img src=\"http://example.com/f.jpg\"></picture>", clean);
514	    }
515	
516	    @Test void emptyOrAllInvalidSourceSrcsetRemovesOnlyTheAttribute() {
517	        Safelist sl = pictureSafelist();
518	        String allInvalid = "<picture><source media=\"(m)\" type=\"image/webp\" srcset=\"javascript:x 1x\">"
519	            + "<img src=\"/f.jpg\"></picture>";
520	        assertEquals("<picture><source media=\"(m)\" type=\"image/webp\">"
521	            + "<img src=\"http://example.com/f.jpg\"></picture>",
522	            Jsoup.clean(allInvalid, "http://example.com/", sl));
523	
524	        String empty = "<picture><source media=\"(m)\" srcset=\"   ,, \"><img src=\"/f.jpg\"></picture>";
525	        assertEquals("<picture><source media=\"(m)\"><img src=\"http://example.com/f.jpg\"></picture>",
526	            Jsoup.clean(empty, "http://example.com/", sl));
527	    }
528	
529	    @Test void sourceTagGatingRemovesTagWhenNotAllowed() {
530	        // picture allowed, but source tag not: the source element itself is gone (children/content hoisted per
531	        // existing unknown-tag rules), media/type/srcset do not survive on it; img is untouched
532	        Safelist sl = Safelist.relaxed().addTags("picture").addAttributes("img", "srcset");
533	        String html = "<picture><source media=\"(m)\" type=\"image/webp\" srcset=\"/a.jpg 1x\"><img src=\"/f.jpg\"></picture>";
534	        String clean = Jsoup.clean(html, "http://example.com/", sl);
535	        assertFalse(clean.contains("<source"), "source must not appear when its tag is not allowed: " + clean);
536	        assertFalse(clean.contains("javascript"));
537	        assertTrue(clean.contains("<img"));
538	    }
539	
540	    @Test void sourceAllowedButSrcsetNotRemovesOnlySrcset() {
541	        Safelist sl = Safelist.relaxed()
542	            .addTags("picture", "source")
543	            .addAttributes("source", "media", "type")
544	            .addAttributes("img", "srcset");
545	        String html = "<picture><source media=\"(m)\" type=\"image/webp\" srcset=\"/a.jpg 1x\"><img src=\"/f.jpg\"></picture>";
546	        String clean = Jsoup.clean(html, "http://example.com/", sl);
547	        assertEquals("<picture><source media=\"(m)\" type=\"image/webp\"><img src=\"http://example.com/f.jpg\"></picture>",
548	            clean);
549	    }
550	
551	    @Test void explicitSourceSrcsetProtocolsStillWinOverImgPolicy() {
552	        // an explicit policy on source is not overridden by the img fallback; here only data: is allowed on source,
553	        // while img keeps http/https
554	        Safelist sl = pictureSafelist().addProtocols("source", "srcset", "data");
555	        String html = "<source srcset=\"data:text/plain,Hi 1x, http://example.com/a.jpg 2x\">";
556	        assertEquals("<source srcset=\"data:text/plain,Hi 1x\">", Jsoup.clean(html, "http://example.com/", sl));
557	    }
558	
