560	        String html = "<picture>"
561	            + "<source media=\"(min-width: 600px)\" srcset=\"/a.jpg 600w, javascript:x 1x\">"
562	            + "<source type=\"image/webp\" srcset=\"/b.webp, /c.webp 2x\">"
563	            + "<img src=\"/f.jpg\" srcset=\"/f.jpg 1x, bad\">"
564	            + "</picture>";
565	        Cleaner cleaner = new Cleaner(pictureSafelist());
566	        Document once = cleaner.clean(Jsoup.parseBodyFragment(html, "http://example.com/"));
567	        Document twice = cleaner.clean(once);
