575	    }
576	
577	    @Test void oneFailingSourceSrcsetDoesNotHalfUpdateOrAffectOthers() {
578	        Document dirty = Jsoup.parseBodyFragment(
579	            "<picture><source srcset=\"javascript:bad\"><source srcset=\"http://example.com/ok.jpg 1x\">"
580	                + "<img srcset=\"http://example.com/img.jpg 2x\"></picture>",
