import org.jsoup.Jsoup;
import org.jsoup.safety.Safelist;

public class Probe {
    static Safelist sl() {
        return Safelist.relaxed()
            .addTags("picture", "source")
            .addAttributes("img", "srcset")
            .addAttributes("source", "srcset", "media", "type");
    }
    static void t(String label, String html) {
        System.out.println(label + " => [" + Jsoup.clean(html, sl()) + "]");
    }
    public static void main(String[] a) {
        t("root-rel img no base", "<img srcset=\"/assets/a.png 1x\">");
        t("rel path img no base", "<img srcset=\"assets/a.png 1x\">");
        t("mixed no base", "<img srcset=\"/assets/a.png 1x, javascript:bad 2x\">");
        t("root-rel source no base", "<source srcset=\"/assets/a.png 1x\">");
        t("scheme-ish", "<img srcset=\"//example.com/a.png 1x\">");
        t("data no base", "<img srcset=\"data:text/plain,Hi 1x, http://example.com/a.jpg 2x\">");
        t("dot rel", "<img srcset=\"./a.png, ../b.png 2x\">");
    }
}
