    public static void main(String[] a) {
        // A: srcset structurally allowed only on source (not img)
        Safelist A = Safelist.relaxed().addTags("picture","source")
            .addAttributes("source","srcset","media","type");
        t("A source-only http+js", "<source srcset=\"http://e.com/a.jpg 1x, javascript:x 2x\">", A);
        t("A img srcset not allowed", "<img src=\"/f.jpg\" srcset=\"http://e.com/a.jpg 1x\">", A);
        // C: :all only, protocols declared on :all srcset
        Safelist C = new Safelist().addTags("img","source")
            .addAttributes(":all","srcset").addProtocols(":all","srcset","http","https");
        t("C all-rule", "<source srcset=\"http://e.com/a.jpg 1x, javascript:x\"><img srcset=\"http://i.com/b.jpg 2x, data:x\">", C);
        // D: tighten source to https only, img untouched
        Safelist D = Safelist.relaxed().addTags("picture","source")
            .addAttributes("img","srcset").addAttributes("source","srcset")
            .addProtocols("source","srcset","https");
        t("D source http+https", "<source srcset=\"http://e.com/a.jpg 1x, https://e.com/b.jpg 2x\">", D);
        t("D img http+https", "<img srcset=\"http://e.com/a.jpg 1x, https://e.com/b.jpg 2x\">", D);
        // E: source loosened with data; img must NOT accept data
        Safelist E = Safelist.relaxed().addTags("source").addAttributes("img","srcset")
            .addAttributes("source","srcset").addProtocols("source","srcset","http","https","data");
        t("E img with data", "<img srcset=\"data:text/plain,Hi 1x, http://e.com/a.jpg 2x\">", E);
        t("E source with data", "<source srcset=\"data:text/plain,Hi 1x, http://e.com/a.jpg 2x\">", E);
    }
}
