        Safelist s3 = Safelist.relaxed().addTags("source")
            .addAttributes("img","srcset").addAttributes("source","srcset")
            .addProtocols("img","srcset","https");
        System.out.println("3 source (fallback https): " + c("<source srcset='http://e.com/a 1x, https://e.com/b 2x'>", s3));

