        // 5: :all http/https, img-specific https override; div uses :all (http allowed), img https only
        Safelist s5 = new Safelist().addTags("img","div")
            .addAttributes(":all","srcset").addProtocols(":all","srcset","http","https")
            .addProtocols("img","srcset","https");
