        System.out.println("5 div: " + c("<div srcset='http://e.com/a 1x, https://e.com/b 2x'></div>", s5));

        // 6: loose source (data) never grants data to img even though srcset attr allowed on both, no img srcset proto -> img src http/https
        Safelist s6 = Safelist.relaxed().addTags("source")
            .addAttributes("img","srcset").addAttributes("source","srcset")
            .addProtocols("source","srcset","http","https","data");
        System.out.println("6 img (no data via source loosening): " + c("<img srcset='data:x 1x, http://e.com/a 2x'>", s6));
    }
}
